'use client';

import * as React from 'react';

// @interlace/photo-upload v1.0.1 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/photo-upload
// What changed since: https://ds.interlace.tools/c/photo-upload#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — PhotoUpload
 *
 * Photos from the five places people get them (pick, drag, paste, camera),
 * made small and clean on the device, then handed to ONE function the app
 * provides, `onUpload`. The component never opens a connection: it has no
 * `fetch`, no `XMLHttpRequest`, no destination. What reaches `onUpload` has
 * no location, camera, time or embedded thumbnail inside it.
 *
 * ## Anatomy
 *
 *   PhotoUpload                    (div role=group — data-slot="photo-upload", data-state, data-count)
 *     ├─ span                      (data-slot="photo-upload-label": the visible name)
 *     ├─ div                       (data-slot="photo-upload-dropzone", data-drag idle|over, data-full)
 *     │   ├─ label > input file    (data-slot="photo-upload-pick": the real control, laid over its label at opacity 0 so it stays focusable)
 *     │   ├─ label > input file    (data-slot="photo-upload-camera": touch devices only, after mount)
 *     │   └─ p                     (data-slot="photo-upload-hint")
 *     ├─ p role=status             (data-slot="photo-upload-rejections")
 *     ├─ ul                        (data-slot="photo-upload-list")
 *     │   └─ li                    (data-slot="photo-upload-item", data-status)
 *     │       ├─ img | span        (data-slot="photo-upload-thumb")
 *     │       ├─ div               (data-slot="photo-upload-meta": name, size, "Location removed")
 *     │       ├─ Progress          (data-slot="photo-upload-progress", only while working)
 *     │       ├─ p                 (data-slot="photo-upload-message": the state in words; role=alert on error)
 *     │       ├─ input text        (data-slot="photo-upload-alt", with `altText`)
 *     │       └─ div               (data-slot="photo-upload-actions": Crop, Try again, Cancel, Remove)
 *     ├─ Button                    (data-slot="photo-upload-submit": `manual` with ready photos)
 *     └─ p aria-live=polite        (data-slot="photo-upload-announce", sr-only)
 *
 * ## Where the photos go
 *
 * `onUpload(photo, ctx)` is the whole backend surface. `ctx.onProgress(0..1)`
 * reports progress, `ctx.signal` aborts on cancel, remove and unmount. Throw
 * `PhotoUploadError({ retryable: true })` for a failure worth retrying (up to
 * `retries`, 1 s, 2 s, 4 s with jitter); any other failure shows Try again.
 * `xhrUploader` (subpath `photo-upload-xhr`) is one ready-made adapter.
 *
 * ## States
 *
 * Component: empty, drag-over, has-items, full, partial-failure, all-done,
 * disabled, read-only, offline-waiting. Item: queued, reading, processing,
 * ready, uploading, done, error, canceled. Each is words and an icon, never
 * colour alone. With JavaScript off the dropzone is a labelled native file
 * input (give it a `name`).
 *
 * ## Source of the API
 *
 * react-dropzone (https://react-dropzone.js.org): `accept`, `maxFiles` keep
 * its names. Uppy (https://uppy.io) and FilePond (https://pqina.nl/filepond):
 * the queue, progress and retry model. Diverges on purpose: `maxFileBytes`
 * names its unit, `onUpload` is an adapter (no destination), no plugin system
 * (the adapter and `runtime` are the extension points).
 *
 * | Rule | Concept              | Where                                   |
 * | ---- | -------------------- | --------------------------------------- |
 * | R5   | data-testid required | `PhotoUploadProps['data-testid']`       |
 * | R6   | data-slot per part   | every part above                        |
 * | R8   | booleans default off | `manual`, `altText`                     |
 * | R14  | controlled + not     | `value` / `defaultValue`                |
 * | R25  | lazy client part     | the cropper loads on first use          |
 * | R26  | A11y                 | native input, one announcement per change |
 */

import {
  AlertCircleIcon,
  CameraIcon,
  CheckCircleIcon,
  CropIcon,
  ImagePlusIcon,
  LoaderCircleIcon,
  RotateCcwIcon,
  XIcon,
} from 'lucide-react';

import { cn } from '@/lib/utils';
import { Button } from '@/components/ui/button';
import { Progress, ProgressIndicator, ProgressTrack } from '@/components/ui/progress';
import {
  announcements,
  DEFAULT_ACCEPT,
  DEFAULT_ERROR_TEXT,
  fingerprintOf,
  formatBytes,
  HEAD_BYTES,
  isLive,
  nextToUpload,
  PhotoUploadError,
  planIntake,
  planProcessing,
  qualityLadder,
  readHeader,
  reduce,
  retryDelay,
  shouldAutoRetry,
  stripMetadata,
  type CropRect,
  type PhotoAction,
  type PhotoError,
  type PhotoErrorCode,
  type PhotoItem,
  type PhotoMime,
  type PhotoProcessing,
  type PhotoUploader,
  type ProcessedPhoto,
  type Quarter,
} from '@/components/ui/patterns/photo-upload-model';
import { browserRuntime, type ImageRuntime } from '@/components/ui/patterns/photo-upload-runtime';

export type { PhotoItem, PhotoMime, PhotoProcessing, PhotoUploader, ProcessedPhoto };
export { PhotoUploadError } from '@/components/ui/patterns/photo-upload-model';

export const MIN_VIEWPORT = 320 as const;

const PhotoCropper = React.lazy(() => import('./photo-upload-crop.js'));

export interface PhotoCrop {
  /** width / height; null for free. @default null */
  aspect?: number | null;
  /** `round` masks the preview only; the output is the full rectangle. @default 'rect' */
  shape?: 'rect' | 'round';
  /** Open the cropper for every added photo before processing. @default false */
  required?: boolean;
}

type Text<A extends unknown[] = []> = string | ((...args: A) => string);
export interface PhotoUploadLabels {
  /** @default 'Photos' */
  label?: string;
  /** @default 'Choose photos' (singular with maxFiles 1) */
  choose?: string;
  /** @default 'Take photo' */
  camera?: string;
  /** @default 'or drag photos here, or paste' */
  hint?: string;
  /** @default 'Upload' */
  upload?: string;
  /** @default 'Crop' */
  crop?: string;
  /** @default 'Try again' */
  retry?: string;
  /** @default 'Cancel' */
  cancel?: string;
  /** @default 'Remove' */
  remove?: string;
  /** @default 'Describe this photo' */
  alt?: string;
  /** @default 'Location removed' */
  locationRemoved?: string;
  /** @default 'Details removed' */
  detailsRemoved?: string;
  /** @default 'You have added the most photos allowed.' */
  full?: string;
  /** @default 'Waiting for a connection' */
  offline?: string;
  /** Per-status words. */
  status?: Partial<Record<PhotoItem['status'], string>>;
  /** Per-error words. */
  errors?: Partial<Record<PhotoErrorCode, string>>;
  /** @default (added, skipped) => '2 added. 1 skipped: not a photo' */
  rejections?: Text<[number, string]>;
  cropper?: {
    title?: string;
    zoom?: string;
    rotateLeft?: string;
    rotateRight?: string;
    apply?: string;
    cancel?: string;
  };
}

export interface PhotoChangeDetails {
  reason: 'added' | 'removed' | 'status' | 'alt' | 'crop' | 'retry' | 'cancel' | 'rejected';
  id: string | null;
  rejected: readonly { name: string; error: PhotoError }[];
}

export interface PhotoItemProps {
  item: PhotoItem;
  index: number;
  total: number;
  labels: Required<Pick<PhotoUploadLabels, 'crop' | 'retry' | 'cancel' | 'remove' | 'alt' | 'locationRemoved' | 'detailsRemoved'>>;
  actions: {
    crop?: () => void;
    retry?: () => void;
    cancel?: () => void;
    remove?: () => void;
    setAlt?: (alt: string) => void;
  };
  message: string;
  altText: boolean;
}

export interface PhotoUploadProps
  extends Omit<React.ComponentPropsWithoutRef<'div'>, 'onChange' | 'defaultValue' | 'children'> {
  'data-testid': string;
  /** The whole backend surface. Required: the component has no default destination. */
  onUpload: PhotoUploader;
  value?: readonly PhotoItem[];
  defaultValue?: readonly PhotoItem[];
  onValueChange?: (items: readonly PhotoItem[], details: PhotoChangeDetails) => void;
  /** @default ['image/jpeg', 'image/png', 'image/webp'] */
  accept?: readonly PhotoMime[];
  /** @default 10 */
  maxFiles?: number;
  /** Largest input file, in bytes, before any processing. @default 26214400 */
  maxFileBytes?: number;
  /** Largest input in pixels, read from the header before decoding. @default 40000000 */
  maxPixels?: number;
  /** `false` skips resize and re-encode but never skips the metadata strip. */
  processing?: PhotoProcessing | false;
  /** `false` hides the Crop action. @default false */
  crop?: PhotoCrop | false;
  /** Adds a "Take photo" button that opens the camera on a touch device. */
  capture?: 'environment' | 'user';
  /** Wait for an Upload button instead of uploading once a photo is processed. @default false */
  manual?: boolean;
  /** @default 3 */
  concurrency?: number;
  /** Automatic tries after a retryable failure. @default 2 */
  retries?: number;
  /** Show a "Describe this photo" field per photo. @default false */
  altText?: boolean;
  disabled?: boolean;
  readOnly?: boolean;
  /** Makes it a real form field: the native input posts the chosen files with JavaScript off. */
  name?: string;
  labels?: PhotoUploadLabels;
  /** Substitute the browser: tests, an agent, a worker, a HEIC decoder. @default browserRuntime */
  runtime?: ImageRuntime;
  random?: () => number;
  makeId?: () => string;
  dropzoneProps?: React.ComponentPropsWithoutRef<'div'>;
  itemComponent?: React.ComponentType<PhotoItemProps>;
}

const STATUS_WORDS: Record<PhotoItem['status'], string> = {
  queued: 'Waiting',
  reading: 'Reading',
  processing: 'Getting it ready',
  ready: 'Ready to upload',
  uploading: 'Uploading',
  done: 'Uploaded',
  error: 'Failed',
  canceled: 'Canceled',
};

const wordsOf = (t: Text<[number, string]> | undefined, added: number, skipped: string, fallback: string) =>
  typeof t === 'function' ? t(added, skipped) : (t ?? fallback);

const STATE_OF = (items: readonly PhotoItem[], max: number, disabled: boolean, readOnly: boolean, online: boolean) => {
  if (disabled) return 'disabled';
  if (readOnly) return 'read-only';
  if (!online) return 'offline-waiting';
  if (items.length === 0) return 'empty';
  if (items.some((i) => i.status === 'error')) return 'partial-failure';
  if (items.every((i) => i.status === 'done')) return 'all-done';
  if (items.filter((i) => isLive(i.status) || i.status === 'done').length >= max) return 'full';
  return 'has-items';
};

function DefaultItem({ item, index, total, labels, actions, message, altText }: PhotoItemProps) {
  const working = item.status === 'processing' || item.status === 'uploading';
  const removed = item.output?.metadataRemoved ?? [];
  const Icon = item.status === 'done' ? CheckCircleIcon : item.status === 'error' ? AlertCircleIcon : null;
  return (
    <li
      data-slot="photo-upload-item"
      data-status={item.status}
      data-id={item.id}
      className="border-border bg-background grid grid-cols-[3.5rem_1fr] gap-x-3 gap-y-2 rounded-lg border p-3 motion-safe:animate-in motion-safe:slide-in-from-bottom-1 motion-safe:duration-(--duration-base)"
    >
      {item.previewUrl ? (
        <img
          data-slot="photo-upload-thumb"
          src={item.previewUrl}
          alt={altText ? item.alt : ''}
          width={56}
          height={56}
          className="bg-muted aspect-square size-14 rounded-md object-cover"
        />
      ) : (
        <span data-slot="photo-upload-thumb" className="bg-muted aspect-square size-14 rounded-md" aria-hidden="true" />
      )}
      <div className="grid min-w-0 gap-1">
        <div data-slot="photo-upload-meta" className="min-w-0 text-sm">
          <p className="truncate font-medium">{item.name}</p>
          <p className="text-muted-foreground">
            {item.output && item.output.bytes < item.source.bytes
              ? `${formatBytes(item.output.bytes)}, was ${formatBytes(item.source.bytes)}`
              : formatBytes(item.output?.bytes ?? item.source.bytes)}
            {removed.length > 0
              ? `. ${removed.includes('gps') ? labels.locationRemoved : labels.detailsRemoved}`
              : ''}
          </p>
        </div>
        {working ? (
          <Progress
            data-slot="photo-upload-progress"
            value={Math.round(item.progress * 100)}
            aria-label={`${item.name}: ${message}`}
            aria-valuetext={`${Math.round(item.progress * 100)} percent, ${message.toLowerCase()}`}
          >
            <ProgressTrack>
              <ProgressIndicator />
            </ProgressTrack>
          </Progress>
        ) : null}
        <p
          data-slot="photo-upload-message"
          role={item.status === 'error' ? 'alert' : undefined}
          className={cn('flex items-center gap-1.5 text-sm', item.status === 'error' ? 'text-destructive' : 'text-muted-foreground')}
        >
          {Icon ? <Icon aria-hidden="true" className="size-4 shrink-0" /> : null}
          {item.status === 'processing' || item.status === 'uploading' || item.status === 'reading' ? (
            <LoaderCircleIcon aria-hidden="true" className="size-4 shrink-0 motion-safe:animate-spin" />
          ) : null}
          <span>{message}</span>
        </p>
        {altText && actions.setAlt ? (
          <input
            data-slot="photo-upload-alt"
            type="text"
            aria-label={`${labels.alt}: ${item.name}`}
            placeholder={labels.alt}
            value={item.alt}
            onChange={(e) => actions.setAlt?.(e.target.value)}
            className="border-input bg-background h-control-sm w-full rounded-md border px-2 text-sm"
          />
        ) : null}
        <div data-slot="photo-upload-actions" className="flex flex-wrap gap-2">
          {actions.crop ? (
            <Button type="button" variant="outline" size="sm" onClick={actions.crop} data-action="crop">
              <CropIcon aria-hidden="true" />
              {labels.crop}
              <span className="sr-only">{`: ${item.name}`}</span>
            </Button>
          ) : null}
          {actions.retry ? (
            <Button type="button" variant="outline" size="sm" onClick={actions.retry} data-action="retry">
              <RotateCcwIcon aria-hidden="true" />
              {labels.retry}
              <span className="sr-only">{`: ${item.name}`}</span>
            </Button>
          ) : null}
          {actions.cancel ? (
            <Button type="button" variant="ghost" size="sm" onClick={actions.cancel} data-action="cancel">
              {labels.cancel}
              <span className="sr-only">{`: ${item.name}`}</span>
            </Button>
          ) : null}
          {actions.remove ? (
            <Button type="button" variant="ghost" size="sm" onClick={actions.remove} data-action="remove">
              <XIcon aria-hidden="true" />
              {labels.remove}
              <span className="sr-only">{`: ${item.name} (${index + 1} of ${total})`}</span>
            </Button>
          ) : null}
        </div>
      </div>
    </li>
  );
}

function PhotoUpload({
  onUpload,
  value,
  defaultValue,
  onValueChange,
  accept = DEFAULT_ACCEPT,
  maxFiles = 10,
  maxFileBytes = 26_214_400,
  maxPixels = 40_000_000,
  processing,
  crop = false,
  capture,
  manual = false,
  concurrency = 3,
  retries = 2,
  altText = false,
  disabled = false,
  readOnly = false,
  name,
  labels,
  runtime = browserRuntime,
  random = Math.random,
  makeId,
  dropzoneProps,
  itemComponent: Item = DefaultItem,
  className,
  ...rest
}: PhotoUploadProps) {
  const baseId = React.useId();
  const nextId = React.useRef(0);
  const newId = makeId ?? (() => `${baseId}-${++nextId.current}`);
  const [inner, setInner] = React.useState<readonly PhotoItem[]>(defaultValue ?? []);
  const items = value ?? inner;
  const itemsRef = React.useRef(items);
  itemsRef.current = items;
  const files = React.useRef(new Map<string, File>());
  const controllers = React.useRef(new Map<string, AbortController>());
  const timers = React.useRef(new Set<ReturnType<typeof setTimeout>>());
  const live = React.useRef(true);
  const [rejections, setRejections] = React.useState<{ added: number; skipped: string[] } | null>(null);
  const [drag, setDrag] = React.useState<'idle' | 'over'>('idle');
  const [online, setOnline] = React.useState(true);
  const wasOnline = React.useRef(true);
  const [released, setReleased] = React.useState(false);
  const [announce, setAnnounce] = React.useState('');
  const [touch, setTouch] = React.useState(false);
  const [cropping, setCropping] = React.useState<string | null>(null);
  const cropButton = React.useRef<HTMLElement | null>(null);
  const prev = React.useRef<readonly PhotoItem[] | null>(null);
  const buffer = React.useRef<string[]>([]);
  const flush = React.useRef<ReturnType<typeof setTimeout> | null>(null);
  const chooseRef = React.useRef<HTMLInputElement>(null);
  const t = labels ?? {};
  const words = {
    label: t.label ?? 'Photos',
    choose: t.choose ?? (maxFiles === 1 ? 'Choose a photo' : 'Choose photos'),
    camera: t.camera ?? 'Take photo',
    hint: t.hint ?? 'or drag photos here, or paste',
    upload: t.upload ?? 'Upload',
    crop: t.crop ?? 'Crop',
    retry: t.retry ?? 'Try again',
    cancel: t.cancel ?? 'Cancel',
    remove: t.remove ?? 'Remove',
    alt: t.alt ?? 'Describe this photo',
    full: t.full ?? 'You have added the most photos allowed.',
    offline: t.offline ?? 'Waiting for a connection',
    locationRemoved: t.locationRemoved ?? 'Location removed',
    detailsRemoved: t.detailsRemoved ?? 'Details removed',
  };
  const errorText = (code: PhotoErrorCode) => t.errors?.[code] ?? DEFAULT_ERROR_TEXT[code];
  const cropOpts = crop === false ? null : crop;

  const commit = React.useCallback(
    (action: PhotoAction, reason: PhotoChangeDetails['reason'], id: string | null, rejected: PhotoChangeDetails['rejected'] = []) => {
      const next = reduce(itemsRef.current, action);
      if (next === itemsRef.current && rejected.length === 0) return;
      itemsRef.current = next;
      if (value === undefined) setInner(next);
      onValueChange?.(next, { reason, id, rejected });
    },
    [onValueChange, value],
  );

  const release = React.useCallback(
    (id: string) => {
      const url = itemsRef.current.find((i) => i.id === id)?.previewUrl;
      if (url) runtime.revokeObjectURL(url);
    },
    [runtime],
  );

  // Processing: read, plan, strip or re-encode, thumbnail. The model decides; the runtime draws.
  const process = React.useCallback(
    async (id: string) => {
      const file = files.current.get(id);
      const item = itemsRef.current.find((i) => i.id === id);
      if (!file || !item) return;
      const controller = controllers.current.get(id) ?? new AbortController();
      controllers.current.set(id, controller);
      const { signal } = controller;
      const fail = (code: PhotoErrorCode, detail?: string) =>
        commit({ type: 'failed', id, error: { code, retryable: code !== 'unsupported-format', detail } }, 'status', id);
      commit({ type: 'reading', id }, 'status', id);
      try {
        const bytes = new Uint8Array(await file.arrayBuffer());
        if (signal.aborted) return;
        const type = (item.source.type as PhotoMime) ?? 'image/jpeg';
        const header = readHeader(bytes, type);
        if (!header) return fail('decode-failed');
        commit({ type: 'processing', id, progress: 0.2 }, 'status', id);
        const plan = planProcessing(header, processing, item.crop);
        const stripped = stripMetadata(bytes, type);
        const edge = processing === false ? Infinity : (processing?.maxEdge ?? 2048);
        const hint = header.width && header.height ? { width: header.width, height: header.height } : undefined;
        const decoded = await runtime.decode(new Blob([bytes as BlobPart], { type }), {
          maxEdge: plan.kind === 'strip-only' ? 320 : edge,
          signal,
          hint:
            hint && header.orientation >= 5
              ? { width: hint.height, height: hint.width }
              : hint,
        });
        if (signal.aborted) {
          if (decoded) runtime.dispose?.(decoded);
          return;
        }
        if (!decoded) return fail('unsupported-format');
        let blob: Blob;
        let outType: PhotoMime = type;
        // Both branches below assign these before they are read.
        let width: number;
        let height: number;
        let removed = stripped.removed;
        const strippedBlob = new Blob([stripped.bytes as BlobPart], { type });
        if (plan.kind === 'strip-only') {
          blob = strippedBlob;
          width = header.width ?? decoded.width;
          height = header.height ?? decoded.height;
        } else {
          let best: Blob | null = null;
          for (const quality of qualityLadder(processing)) {
            if (signal.aborted) return;
            best = await runtime.encode(decoded, { ...plan, quality }, signal);
            const target = processing === false ? undefined : processing?.targetBytes;
            if (!target || best.size <= target) break;
          }
          blob = best as Blob;
          outType = plan.type;
          width = plan.width || decoded.width;
          height = plan.height || decoded.height;
          removed = header.metadata.length ? [...header.metadata] : [];
          // A resize never makes a file bigger: keep the stripped original when it is smaller and unchanged in look.
          if (
            plan.crop === null &&
            plan.quarter === 0 &&
            header.orientation === 1 &&
            header.width !== null &&
            blob.size >= strippedBlob.size &&
            plan.type === type
          ) {
            blob = strippedBlob;
            outType = type;
            width = header.width;
            height = header.height ?? height;
            removed = stripped.removed;
          }
        }
        const thumb = await runtime.thumbnail(decoded, 320);
        runtime.dispose?.(decoded);
        if (signal.aborted) return;
        const previewUrl = runtime.createObjectURL(thumb);
        const output: ProcessedPhoto = {
          blob,
          type: outType,
          width,
          height,
          bytes: blob.size,
          metadataRemoved: removed,
          alt: item.alt,
        };
        if (!live.current) return runtime.revokeObjectURL(previewUrl);
        const old = itemsRef.current.find((i) => i.id === id)?.previewUrl;
        if (old) runtime.revokeObjectURL(old);
        commit({ type: 'processed', id, output, previewUrl }, 'status', id);
      } catch (e) {
        if (signal.aborted) return;
        fail('encode-failed', e instanceof Error ? e.message : undefined);
      }
    },
    [commit, processing, runtime],
  );

  const startUpload = React.useCallback(
    (id: string) => {
      const item = itemsRef.current.find((i) => i.id === id);
      if (!item?.output) return;
      const controller = new AbortController();
      controllers.current.set(id, controller);
      commit({ type: 'upload', id }, 'status', id);
      onUpload(item.output, {
        id,
        signal: controller.signal,
        attempt: item.attempt,
        onProgress: (value) => {
          if (!controller.signal.aborted) commit({ type: 'progress', id, value }, 'status', id);
        },
      }).then(
        (result) => {
          if (!controller.signal.aborted) commit({ type: 'resolved', id, result }, 'status', id);
        },
        (e: unknown) => {
          if (controller.signal.aborted) return;
          // `retryable` on the error means "Try again is offered": always, for a failed upload.
          // Trying again by itself is for the adapter to ask for, with `PhotoUploadError({ retryable: true })`.
          const byItself = e instanceof PhotoUploadError && e.options.retryable;
          const error: PhotoError = {
            code: 'upload-failed',
            retryable: true,
            detail: e instanceof Error ? e.message : undefined,
          };
          commit({ type: 'failed', id, error }, 'status', id);
          if (shouldAutoRetry({ ...error, retryable: byItself }, item.attempt, retries)) {
            const timer = setTimeout(() => {
              timers.current.delete(timer);
              if (live.current) commit({ type: 'retry', id }, 'retry', id);
            }, retryDelay(item.attempt, random));
            timers.current.add(timer);
          }
        },
      );
    },
    [commit, onUpload, random, retries],
  );

  // Uploads start when a slot is free, the network is up, and (manual) the person said go.
  React.useEffect(() => {
    for (const id of nextToUpload(items, { concurrency, online, manual, released })) startUpload(id);
    if (manual && released && !items.some((i) => i.status === 'ready' || i.status === 'uploading')) setReleased(false);
  }, [items, concurrency, online, manual, released, startUpload]);

  // Online and touch are read after mount, so the server and first client render agree.
  React.useEffect(() => {
    setTouch(typeof navigator !== 'undefined' && navigator.maxTouchPoints > 0);
    setOnline(typeof navigator === 'undefined' ? true : navigator.onLine !== false);
    const up = () => setOnline(true);
    const down = () => setOnline(false);
    window.addEventListener('online', up);
    window.addEventListener('offline', down);
    return () => {
      window.removeEventListener('online', up);
      window.removeEventListener('offline', down);
    };
  }, []);

  // One announcement per change, coalesced over 400 ms. Nothing on the first render.
  React.useEffect(() => {
    const said = announcements(prev.current, items, { online, wasOnline: wasOnline.current, text: t.errors });
    prev.current = items;
    wasOnline.current = online;
    if (said.length === 0) return;
    buffer.current.push(...said);
    if (flush.current) clearTimeout(flush.current);
    flush.current = setTimeout(() => {
      setAnnounce(buffer.current.join('. '));
      buffer.current = [];
      flush.current = null;
    }, 400);
  });

  // Unmount aborts every item, clears timers and revokes every preview.
  React.useEffect(() => {
    live.current = true;
    const ctrl = controllers.current;
    const tm = timers.current;
    return () => {
      live.current = false;
      for (const c of ctrl.values()) c.abort();
      for (const timer of tm) clearTimeout(timer);
      if (flush.current) clearTimeout(flush.current);
      for (const i of itemsRef.current) if (i.previewUrl) runtime.revokeObjectURL(i.previewUrl);
    };
  }, [runtime]);

  const addFiles = React.useCallback(
    async (list: File[]) => {
      if (disabled || readOnly || list.length === 0) return;
      const heads = await Promise.all(
        list.map(async (f) => ({
          name: f.name,
          size: f.size,
          lastModified: f.lastModified,
          head: new Uint8Array(await f.slice(0, HEAD_BYTES).arrayBuffer()),
        })),
      );
      const intake = planIntake(heads, itemsRef.current, { accept, maxFiles, maxFileBytes, maxPixels });
      const made: PhotoItem[] = intake.accepted.map((a) => {
        const f = list[a.index] as File;
        const id = newId();
        files.current.set(id, f);
        return {
          id,
          name: f.name,
          status: 'queued',
          progress: 0,
          attempt: 0,
          source: { bytes: f.size, type: a.type, width: a.header.width, height: a.header.height },
          output: null,
          previewUrl: null,
          alt: '',
          crop: { rect: null, quarter: 0 },
          error: null,
          result: null,
          fingerprint: fingerprintOf({ name: f.name, size: f.size, lastModified: f.lastModified }),
        };
      });
      const rejected = intake.rejected.map((r) => ({ name: r.name, error: r.error }));
      setRejections(
        rejected.length || made.length
          ? { added: made.length, skipped: [...new Set(rejected.map((r) => errorText(r.error.code)))] }
          : null,
      );
      if (made.length > 0) commit({ type: 'add', items: made }, 'added', made[0]?.id ?? null, rejected);
      else if (rejected.length > 0) {
        onValueChange?.(itemsRef.current, { reason: 'rejected', id: null, rejected });
      }
      for (const m of made) {
        if (cropOpts?.required) setCropping((c) => c ?? m.id);
        else void process(m.id);
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [accept, commit, cropOpts?.required, disabled, maxFileBytes, maxFiles, maxPixels, onValueChange, process, readOnly],
  );

  const onPick = (e: React.ChangeEvent<HTMLInputElement>) => {
    const picked = Array.from(e.target.files ?? []);
    if (!name) e.target.value = '';
    void addFiles(picked);
  };
  const hasFiles = (e: React.DragEvent) => Array.from(e.dataTransfer?.types ?? []).includes('Files');
  const fullNow = items.filter((i) => i.status !== 'canceled' && i.status !== 'error').length >= maxFiles;
  const state = STATE_OF(items, maxFiles, disabled, readOnly, online);
  const interactive = !disabled && !readOnly;

  const remove = (id: string) => {
    const order = itemsRef.current.map((i) => i.id);
    const at = order.indexOf(id);
    controllers.current.get(id)?.abort();
    release(id);
    files.current.delete(id);
    commit({ type: 'remove', id }, 'removed', id);
    const target = order[at + 1] ?? order[at - 1];
    queueMicrotask(() => {
      const root = document.querySelector<HTMLElement>(`[data-photo-upload="${baseId}"]`);
      const btn = target
        ? root?.querySelector<HTMLElement>(`[data-id="${target}"] [data-action="remove"]`)
        : chooseRef.current;
      btn?.focus();
    });
  };
  const cancel = (id: string) => {
    controllers.current.get(id)?.abort();
    commit({ type: 'cancel', id }, 'cancel', id);
  };
  const messageOf = (item: PhotoItem) => {
    if (item.status === 'error' && item.error) {
      const why = errorText(item.error.code);
      return item.error.detail && item.error.code === 'upload-failed' ? `${why}: ${item.error.detail}` : why;
    }
    return t.status?.[item.status] ?? STATUS_WORDS[item.status];
  };

  const cropTarget = cropping ? items.find((i) => i.id === cropping) : undefined;
  const restart = (id: string, next: PhotoItem['crop']) => {
    commit({ type: 'crop', id, crop: next }, 'crop', id);
    const item = itemsRef.current.find((i) => i.id === id);
    if (item?.status === 'ready' || item?.status === 'error') {
      itemsRef.current = itemsRef.current.map((i) => (i.id === id ? { ...i, status: 'queued', output: null, error: null } : i));
    }
    void process(id);
  };
  const readyCount = items.filter((i) => i.status === 'ready').length;

  return (
    <div
      role="group"
      aria-labelledby={`${baseId}-label`}
      data-slot="photo-upload"
      data-photo-upload={baseId}
      data-state={state}
      data-count={items.length}
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('@container grid gap-3', className)}
      onPaste={(e) => {
        const pasted = Array.from(e.clipboardData?.files ?? []).filter((f) => f.type.startsWith('image/'));
        if (pasted.length > 0 && interactive) {
          e.preventDefault();
          void addFiles(pasted);
        }
      }}
      {...rest}
    >
      <span id={`${baseId}-label`} data-slot="photo-upload-label" className="text-sm font-medium">
        {words.label}
      </span>
      <div
        data-slot="photo-upload-dropzone"
        data-drag={drag}
        data-full={fullNow ? '' : undefined}
        {...dropzoneProps}
        onDragEnter={(e) => {
          dropzoneProps?.onDragEnter?.(e);
          if (interactive && !fullNow && hasFiles(e)) setDrag('over');
        }}
        onDragOver={(e) => {
          dropzoneProps?.onDragOver?.(e);
          if (interactive && hasFiles(e)) e.preventDefault();
        }}
        onDragLeave={(e) => {
          dropzoneProps?.onDragLeave?.(e);
          setDrag('idle');
        }}
        onDrop={(e) => {
          dropzoneProps?.onDrop?.(e);
          setDrag('idle');
          if (!interactive || !hasFiles(e)) return;
          e.preventDefault();
          void addFiles(Array.from(e.dataTransfer.files));
        }}
        className={cn(
          'border-border bg-muted/40 grid min-h-32 place-items-center gap-2 rounded-lg border border-dashed p-4 text-center motion-safe:transition-colors',
          drag === 'over' && 'border-primary bg-primary/10',
          // Only the controls dim (has-[:disabled]:opacity-50 on them): dimming the whole zone took the hint below 4.5:1.
          dropzoneProps?.className,
        )}
      >
        <div className="flex flex-wrap items-center justify-center gap-2">
          <label
            data-slot="photo-upload-pick"
            className="has-[:focus-visible]:ring-ring relative border-input bg-background hover:bg-accent inline-flex h-control cursor-pointer items-center gap-2 rounded-lg border px-4 text-sm font-medium has-[:focus-visible]:ring-2 has-[:disabled]:pointer-events-none has-[:disabled]:opacity-50"
          >
            <ImagePlusIcon aria-hidden="true" className="size-4" />
            {words.choose}
            <input
              ref={chooseRef}
              type="file"
              name={name}
              accept={accept.join(',')}
              multiple={maxFiles > 1}
              disabled={disabled || readOnly || fullNow}
              onChange={onPick}
              className="absolute inset-0 size-full cursor-pointer opacity-0 disabled:cursor-not-allowed"
            />
          </label>
          {capture && touch ? (
            <label
              data-slot="photo-upload-camera"
              className="has-[:focus-visible]:ring-ring relative border-input bg-background hover:bg-accent inline-flex h-control cursor-pointer items-center gap-2 rounded-lg border px-4 text-sm font-medium has-[:focus-visible]:ring-2 has-[:disabled]:pointer-events-none has-[:disabled]:opacity-50"
            >
              <CameraIcon aria-hidden="true" className="size-4" />
              {words.camera}
              <input
                type="file"
                accept="image/*"
                capture={capture}
                disabled={disabled || readOnly || fullNow}
                onChange={onPick}
                className="absolute inset-0 size-full cursor-pointer opacity-0 disabled:cursor-not-allowed"
              />
            </label>
          ) : null}
        </div>
        <p data-slot="photo-upload-hint" className="text-muted-foreground text-sm">
          {fullNow ? words.full : !online ? words.offline : words.hint}
        </p>
      </div>
      {rejections && (rejections.skipped.length > 0 || rejections.added > 0) ? (
        <p role="status" data-slot="photo-upload-rejections" className="text-muted-foreground text-sm">
          {rejections.skipped.length === 0
            ? null
            : wordsOf(
                t.rejections,
                rejections.added,
                rejections.skipped.join(', '),
                `${rejections.added} added. Skipped: ${rejections.skipped.join(', ')}`,
              )}
        </p>
      ) : null}
      {items.length > 0 ? (
        <ul data-slot="photo-upload-list" aria-label={words.label} className="grid gap-2">
          {items.map((item, index) => {
            const canCrop = cropOpts && interactive && (item.status === 'ready' || item.status === 'error' || item.status === 'queued');
            return (
              <Item
                key={item.id}
                item={item}
                index={index}
                total={items.length}
                altText={altText}
                message={messageOf(item)}
                labels={{
                  crop: words.crop,
                  retry: words.retry,
                  cancel: words.cancel,
                  remove: words.remove,
                  alt: words.alt,
                  locationRemoved: words.locationRemoved,
                  detailsRemoved: words.detailsRemoved,
                }}
                actions={{
                  crop: canCrop
                    ? () => {
                        cropButton.current = document.activeElement as HTMLElement;
                        setCropping(item.id);
                      }
                    : undefined,
                  retry:
                    item.status === 'error' && item.error?.retryable && interactive
                      ? () => {
                          commit({ type: 'retry', id: item.id }, 'retry', item.id);
                          if (!itemsRef.current.find((i) => i.id === item.id)?.output) void process(item.id);
                        }
                      : undefined,
                  cancel:
                    interactive && ['queued', 'reading', 'processing', 'uploading'].includes(item.status)
                      ? () => cancel(item.id)
                      : undefined,
                  remove: interactive ? () => remove(item.id) : undefined,
                  setAlt: interactive ? (alt) => commit({ type: 'alt', id: item.id, alt }, 'alt', item.id) : undefined,
                }}
              />
            );
          })}
        </ul>
      ) : null}
      {manual && readyCount > 0 && interactive ? (
        <Button type="button" data-slot="photo-upload-submit" onClick={() => setReleased(true)}>
          {words.upload}
        </Button>
      ) : null}
      <p data-slot="photo-upload-announce" aria-live="polite" aria-atomic="true" className="sr-only">
        {announce}
      </p>
      {cropTarget && cropOpts !== null ? (
        <React.Suspense fallback={null}>
          <PhotoCropper
            item={cropTarget}
            aspect={cropOpts.aspect ?? null}
            shape={cropOpts.shape ?? 'rect'}
            labels={t.cropper}
            onApply={(next: { rect: CropRect | null; quarter: Quarter }) => {
              const id = cropTarget.id;
              setCropping(null);
              if (cropOpts.required && cropTarget.status === 'queued' && !cropTarget.output) {
                commit({ type: 'crop', id, crop: next }, 'crop', id);
                void process(id);
              } else restart(id, next);
              cropButton.current?.focus();
            }}
            onCancel={() => {
              const id = cropTarget.id;
              setCropping(null);
              if (cropOpts.required && cropTarget.status === 'queued' && !cropTarget.output) remove(id);
              cropButton.current?.focus();
            }}
          />
        </React.Suspense>
      ) : null}
    </div>
  );
}

export { PhotoUpload };

export type PhotoMime = 'image/jpeg' | 'image/png' | 'image/webp' | 'image/avif';
export type PhotoStatus =
  | 'queued'
  | 'reading'
  | 'processing'
  | 'ready'
  | 'uploading'
  | 'done'
  | 'error'
  | 'canceled';
export type MetadataKind = 'exif' | 'gps' | 'xmp' | 'iptc' | 'text' | 'thumbnail';
export type Quarter = 0 | 90 | 180 | 270;
/** Fractions (0..1) of the image as shown: oriented, then turned by `quarter`. */
export interface CropRect {
  x: number;
  y: number;
  width: number;
  height: number;
}
export type PhotoErrorCode =
  | 'type-not-allowed'
  | 'too-many'
  | 'file-too-large'
  | 'too-many-pixels'
  | 'duplicate'
  | 'decode-failed'
  | 'unsupported-format'
  | 'encode-failed'
  | 'upload-failed'
  | 'canceled';
export interface PhotoError {
  code: PhotoErrorCode;
  retryable: boolean;
  detail?: string;
}
export interface ProcessedPhoto {
  blob: Blob;
  type: PhotoMime;
  width: number;
  height: number;
  bytes: number;
  /** What was found and removed. Empty when the file had none. */
  metadataRemoved: readonly MetadataKind[];
  alt: string;
}
export interface PhotoItem {
  id: string;
  name: string;
  status: PhotoStatus;
  progress: number;
  attempt: number;
  source: { bytes: number; type: string; width: number | null; height: number | null };
  output: ProcessedPhoto | null;
  previewUrl: string | null;
  alt: string;
  crop: { rect: CropRect | null; quarter: Quarter };
  error: PhotoError | null;
  result: unknown;
  /** name + size + lastModified, the duplicate key. */
  fingerprint: string;
}
export interface EncodePlan {
  /** Output size in pixels. */
  width: number;
  height: number;
  /** EXIF orientation 1..8 of the source. */
  orientation: number;
  quarter: Quarter;
  crop: CropRect | null;
  type: 'image/jpeg' | 'image/png' | 'image/webp';
  quality: number;
}

export interface UploadContext {
  id: string;
  /** Aborted on cancel, remove and unmount. The adapter must stop work when it fires. */
  signal: AbortSignal;
  /** 0..1. Ignored after the signal aborts. */
  onProgress: (fraction: number) => void;
  /** 0 on the first try. */
  attempt: number;
}
export type PhotoUploader = (photo: ProcessedPhoto, ctx: UploadContext) => Promise<unknown>;

/** Throw this from `onUpload` to say what happened. Any other error is shown as `upload-failed` and is not retried by itself. */
export class PhotoUploadError extends Error {
  readonly options: { retryable: boolean; code?: 'network' | 'server' | 'rejected' | 'auth' };
  constructor(message: string, options: { retryable: boolean; code?: 'network' | 'server' | 'rejected' | 'auth' }) {
    super(message);
    this.name = 'PhotoUploadError';
    this.options = options;
  }
}

export const DEFAULT_ACCEPT: readonly PhotoMime[] = ['image/jpeg', 'image/png', 'image/webp'];
export const HEAD_BYTES = 256 * 1024;

/* ------------------------------------------------------------------ sniff */

const startsWith = (b: Uint8Array, sig: readonly number[], at = 0) =>
  b.length >= at + sig.length && sig.every((v, i) => b[at + i] === v);
const ascii = (b: Uint8Array, at: number, len: number) => {
  let s = '';
  for (let i = at; i < Math.min(at + len, b.length); i++) s += String.fromCharCode(b[i] as number);
  return s;
};

/** The image type a file really is, from its first bytes; null for anything else (SVG, GIF, empty). */
export function sniffImage(b: Uint8Array): PhotoMime | null {
  if (startsWith(b, [0xff, 0xd8, 0xff])) return 'image/jpeg';
  if (startsWith(b, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) return 'image/png';
  if (ascii(b, 0, 4) === 'RIFF' && ascii(b, 8, 4) === 'WEBP') return 'image/webp';
  if (ascii(b, 4, 4) === 'ftyp' && /avi[fs]/.test(ascii(b, 8, 24))) return 'image/avif';
  return null;
}

/* ------------------------------------------------------------------- scan */

interface Segment {
  /** Byte range [start, end) in the file. */
  start: number;
  end: number;
  /** Kinds this segment holds; empty for a segment we keep. */
  kinds: MetadataKind[];
  drop: boolean;
}
interface Scan {
  width: number | null;
  height: number | null;
  orientation: number;
  hasAlpha: boolean;
  segments: Segment[];
  /** Where the image data begins, for JPEG. */
  tail: number;
}

const u16 = (b: Uint8Array, at: number, little = false) =>
  little ? (b[at] as number) | ((b[at + 1] as number) << 8) : ((b[at] as number) << 8) | (b[at + 1] as number);
const u32 = (b: Uint8Array, at: number, little = false) =>
  little
    ? ((b[at] as number) | ((b[at + 1] as number) << 8) | ((b[at + 2] as number) << 16) | ((b[at + 3] as number) << 24)) >>> 0
    : (((b[at] as number) << 24) | ((b[at + 1] as number) << 16) | ((b[at + 2] as number) << 8) | (b[at + 3] as number)) >>> 0;

/** What an Exif block (a TIFF structure) holds: orientation, GPS, and an IFD1 thumbnail. */
function readTiff(b: Uint8Array, base: number, end: number) {
  const out = { orientation: 1, gps: false, thumbnail: false };
  if (end - base < 8) return out;
  const order = ascii(b, base, 2);
  if (order !== 'II' && order !== 'MM') return out;
  const little = order === 'II';
  const ifd0 = u32(b, base + 4, little);
  const walk = (offset: number, first: boolean): number => {
    const at = base + offset;
    if (offset < 8 || at + 2 > end) return 0;
    const n = u16(b, at, little);
    for (let i = 0; i < n && at + 2 + (i + 1) * 12 <= end; i++) {
      const e = at + 2 + i * 12;
      const tag = u16(b, e, little);
      if (first && tag === 0x0112) out.orientation = u16(b, e + 8, little);
      if (first && tag === 0x8825) out.gps = true;
    }
    const next = at + 2 + n * 12;
    return next + 4 <= end ? u32(b, next, little) : 0;
  };
  const next = walk(ifd0, true);
  if (next) {
    out.thumbnail = true;
    walk(next, false);
  }
  if (out.orientation < 1 || out.orientation > 8) out.orientation = 1;
  return out;
}

function scanJpeg(b: Uint8Array): Scan | null {
  if (!startsWith(b, [0xff, 0xd8])) return null;
  const scan: Scan = { width: null, height: null, orientation: 1, hasAlpha: false, segments: [], tail: b.length };
  let at = 2;
  while (at + 4 <= b.length) {
    if (b[at] !== 0xff) return scan.width === null ? null : scan;
    const marker = b[at + 1] as number;
    if (marker === 0xff) {
      at += 1;
      continue;
    }
    if (marker === 0xda) {
      scan.tail = at;
      break;
    }
    if (marker === 0xd8 || (marker >= 0xd0 && marker <= 0xd7) || marker === 0x01) {
      at += 2;
      continue;
    }
    const len = u16(b, at + 2);
    if (len < 2 || at + 2 + len > b.length) return scan.width === null ? null : scan;
    const start = at;
    const end = at + 2 + len;
    const kinds: MetadataKind[] = [];
    if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
      scan.height = u16(b, at + 5);
      scan.width = u16(b, at + 7);
    } else if (marker === 0xe1 && ascii(b, at + 4, 6) === 'Exif\0\0') {
      const t = readTiff(b, at + 10, end);
      scan.orientation = t.orientation;
      kinds.push('exif');
      if (t.gps) kinds.push('gps');
      if (t.thumbnail) kinds.push('thumbnail');
    } else if (marker === 0xe1 && ascii(b, at + 4, 28).startsWith('http://ns.adobe.com/xap/1.0/')) {
      kinds.push('xmp');
    } else if (marker === 0xed) {
      kinds.push('iptc');
    } else if (marker === 0xfe) {
      kinds.push('text');
    }
    scan.segments.push({ start, end, kinds, drop: kinds.length > 0 });
    at = end;
  }
  return scan.width === null ? null : scan;
}

function scanPng(b: Uint8Array): Scan | null {
  if (!startsWith(b, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]) || b.length < 33) return null;
  if (ascii(b, 12, 4) !== 'IHDR') return null;
  const colour = b[25] as number;
  const scan: Scan = {
    width: u32(b, 16),
    height: u32(b, 20),
    orientation: 1,
    hasAlpha: colour === 4 || colour === 6,
    segments: [],
    tail: b.length,
  };
  let at = 8;
  while (at + 12 <= b.length) {
    const len = u32(b, at);
    const type = ascii(b, at + 4, 4);
    const end = at + 12 + len;
    if (end > b.length) break;
    const kinds: MetadataKind[] = [];
    if (type === 'tRNS') scan.hasAlpha = true;
    if (type === 'eXIf') {
      const t = readTiff(b, at + 8, at + 8 + len);
      scan.orientation = t.orientation;
      kinds.push('exif');
      if (t.gps) kinds.push('gps');
      if (t.thumbnail) kinds.push('thumbnail');
    } else if (type === 'tEXt' || type === 'zTXt' || type === 'tIME') kinds.push('text');
    else if (type === 'iTXt') kinds.push(ascii(b, at + 8, 17) === 'XML:com.adobe.xmp' ? 'xmp' : 'text');
    scan.segments.push({ start: at, end, kinds, drop: kinds.length > 0 });
    at = end;
    if (type === 'IEND') break;
  }
  return scan;
}

function scanWebp(b: Uint8Array): Scan | null {
  if (ascii(b, 0, 4) !== 'RIFF' || ascii(b, 8, 4) !== 'WEBP') return null;
  const scan: Scan = { width: null, height: null, orientation: 1, hasAlpha: false, segments: [], tail: b.length };
  let at = 12;
  while (at + 8 <= b.length) {
    const type = ascii(b, at, 4);
    const len = u32(b, at + 4, true);
    const data = at + 8;
    const end = data + len + (len % 2);
    const kinds: MetadataKind[] = [];
    if (type === 'VP8X' && data + 10 <= b.length) {
      scan.hasAlpha = ((b[data] as number) & 0x10) !== 0;
      scan.width = 1 + ((b[data + 4] as number) | ((b[data + 5] as number) << 8) | ((b[data + 6] as number) << 16));
      scan.height = 1 + ((b[data + 7] as number) | ((b[data + 8] as number) << 8) | ((b[data + 9] as number) << 16));
    } else if (type === 'VP8 ' && scan.width === null && data + 10 <= b.length && startsWith(b, [0x9d, 0x01, 0x2a], data + 3)) {
      scan.width = u16(b, data + 6, true) & 0x3fff;
      scan.height = u16(b, data + 8, true) & 0x3fff;
    } else if (type === 'VP8L' && scan.width === null && data + 5 <= b.length && b[data] === 0x2f) {
      const bits = u32(b, data + 1, true);
      scan.width = (bits & 0x3fff) + 1;
      scan.height = ((bits >>> 14) & 0x3fff) + 1;
      scan.hasAlpha = ((bits >>> 28) & 1) === 1;
    } else if (type === 'EXIF') {
      const skip = ascii(b, data, 6) === 'Exif\0\0' ? 6 : 0;
      const t = readTiff(b, data + skip, Math.min(data + len, b.length));
      scan.orientation = t.orientation;
      kinds.push('exif');
      if (t.gps) kinds.push('gps');
      if (t.thumbnail) kinds.push('thumbnail');
    } else if (type === 'XMP ') kinds.push('xmp');
    else if (type === 'ALPH') scan.hasAlpha = true;
    scan.segments.push({ start: at, end: Math.min(end, b.length), kinds, drop: kinds.length > 0 });
    at = end;
  }
  return scan.width === null ? null : scan;
}

function scanOf(b: Uint8Array, type: PhotoMime): Scan | null {
  if (type === 'image/jpeg') return scanJpeg(b);
  if (type === 'image/png') return scanPng(b);
  if (type === 'image/webp') return scanWebp(b);
  return null;
}

export interface PhotoHeader {
  type: PhotoMime;
  width: number | null;
  height: number | null;
  /** EXIF orientation 1..8 (1 when absent). */
  orientation: number;
  hasAlpha: boolean;
  metadata: readonly MetadataKind[];
}

const KIND_ORDER: readonly MetadataKind[] = ['exif', 'gps', 'thumbnail', 'xmp', 'iptc', 'text'];
const kindsOf = (scan: Scan): MetadataKind[] => {
  const present = new Set(scan.segments.flatMap((s) => s.kinds));
  return KIND_ORDER.filter((k) => present.has(k));
};

/** Width, height, orientation, alpha and the metadata kinds a file carries; null when the header cannot be read. */
export function readHeader(b: Uint8Array, type: PhotoMime): PhotoHeader | null {
  if (type === 'image/avif') return { type, width: null, height: null, orientation: 1, hasAlpha: false, metadata: [] };
  const scan = scanOf(b, type);
  if (!scan) return null;
  return {
    type,
    width: scan.width,
    height: scan.height,
    orientation: scan.orientation,
    hasAlpha: scan.hasAlpha,
    metadata: kindsOf(scan),
  };
}

const concat = (parts: Uint8Array[]) => {
  const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of parts) {
    out.set(p, at);
    at += p.length;
  }
  return out;
};

/** The same image with its metadata segments cut out. A file with none comes back unchanged. */
export function stripMetadata(b: Uint8Array, type: PhotoMime): { bytes: Uint8Array; removed: MetadataKind[] } {
  const scan = scanOf(b, type);
  if (!scan) return { bytes: b, removed: [] };
  const removed = kindsOf(scan);
  const drops = scan.segments.filter((s) => s.drop);
  if (drops.length === 0) return { bytes: b, removed: [] };
  const parts: Uint8Array[] = [];
  let at = 0;
  for (const d of drops) {
    parts.push(b.subarray(at, d.start));
    at = d.end;
  }
  parts.push(b.subarray(at));
  const out = concat(parts);
  if (type === 'image/webp') {
    const size = out.length - 8;
    out[4] = size & 0xff;
    out[5] = (size >>> 8) & 0xff;
    out[6] = (size >>> 16) & 0xff;
    out[7] = (size >>> 24) & 0xff;
    if (ascii(out, 12, 4) === 'VP8X') out[20] = (out[20] as number) & ~0x0c; // EXIF and XMP flags
  }
  return { bytes: out, removed };
}

/* ------------------------------------------------------------------- plan */

export interface PhotoProcessing {
  maxEdge?: number;
  quality?: number;
  type?: 'auto' | 'image/jpeg' | 'image/webp';
  targetBytes?: number;
  minQuality?: number;
}
export const PROCESSING_DEFAULTS = { maxEdge: 2048, quality: 0.82, minQuality: 0.5 } as const;

export type ProcessingPlan = { kind: 'strip-only' } | ({ kind: 'reencode' } & EncodePlan);

const swaps = (orientation: number) => orientation >= 5 && orientation <= 8;

/** The size of the oriented source, before any crop. */
export function orientedSize(header: Pick<PhotoHeader, 'width' | 'height' | 'orientation'>) {
  const w = header.width ?? 0;
  const h = header.height ?? 0;
  return swaps(header.orientation) ? { width: h, height: w } : { width: w, height: h };
}

/** Strip the bytes when the file already fits; otherwise resize, orient, crop and encode. */
export function planProcessing(
  header: PhotoHeader,
  processing: PhotoProcessing | false | undefined,
  crop: { rect: CropRect | null; quarter: Quarter } = { rect: null, quarter: 0 },
): ProcessingPlan {
  const opts = processing === false ? null : { ...PROCESSING_DEFAULTS, ...processing };
  const base = orientedSize(header);
  const cropped = crop.rect !== null || crop.quarter !== 0;
  const needsOrient = header.orientation !== 1;
  // The crop rectangle lives in the image as the person sees it: oriented, then turned.
  const turned = crop.quarter === 90 || crop.quarter === 270;
  const src = turned ? { width: base.height, height: base.width } : base;
  const w = crop.rect ? Math.max(1, Math.round(src.width * crop.rect.width)) : src.width;
  const h = crop.rect ? Math.max(1, Math.round(src.height * crop.rect.height)) : src.height;
  const maxEdge = opts?.maxEdge ?? Infinity;
  const scale = Math.min(1, maxEdge / Math.max(w, h, 1));
  const convert = processing !== false && processing?.type && processing.type !== 'auto';
  const unknownSize = header.width === null; // AVIF: the bytes cannot be stripped here, so the pixels are redrawn
  if (!cropped && !needsOrient && scale === 1 && !convert && !unknownSize) return { kind: 'strip-only' };
  const wanted = processing === false ? 'auto' : (processing?.type ?? 'auto');
  const type: EncodePlan['type'] =
    wanted !== 'auto'
      ? header.hasAlpha && wanted === 'image/jpeg'
        ? 'image/png'
        : wanted
      : header.type === 'image/png'
        ? 'image/png'
        : header.type === 'image/jpeg'
          ? 'image/jpeg'
          : 'image/webp';
  return {
    kind: 'reencode',
    width: unknownSize ? 0 : Math.max(1, Math.round(w * scale)),
    height: unknownSize ? 0 : Math.max(1, Math.round(h * scale)),
    orientation: header.orientation,
    quarter: crop.quarter,
    crop: crop.rect,
    type,
    quality: opts?.quality ?? PROCESSING_DEFAULTS.quality,
  };
}

/** Qualities to try, at most three, never below `minQuality`, for a `targetBytes` goal. */
export function qualityLadder(processing: PhotoProcessing | false | undefined): number[] {
  const o = processing === false ? undefined : processing;
  const start = o?.quality ?? PROCESSING_DEFAULTS.quality;
  const floor = o?.minQuality ?? PROCESSING_DEFAULTS.minQuality;
  if (!o?.targetBytes) return [start];
  const ladder = [start, start - (start - floor) / 2, floor].map((q) => Math.round(Math.max(floor, q) * 100) / 100);
  return [...new Set(ladder)];
}

/* ----------------------------------------------------------------- intake */

export interface IntakeFile {
  name: string;
  size: number;
  lastModified: number;
  /** The first HEAD_BYTES bytes. */
  head: Uint8Array;
}
export interface IntakeOptions {
  accept: readonly PhotoMime[];
  maxFiles: number;
  maxFileBytes: number;
  maxPixels: number;
}
export interface Intake {
  accepted: { index: number; type: PhotoMime; header: PhotoHeader; fingerprint: string }[];
  rejected: { index: number; name: string; error: PhotoError }[];
}

export const fingerprintOf = (f: Pick<IntakeFile, 'name' | 'size' | 'lastModified'>) =>
  `${f.name}:${f.size}:${f.lastModified}`;

/** Decide, file by file, what becomes an item. One bad file never rejects the batch. */
export function planIntake(files: readonly IntakeFile[], existing: readonly PhotoItem[], opts: IntakeOptions): Intake {
  const out: Intake = { accepted: [], rejected: [] };
  const live = existing.filter((i) => i.status !== 'canceled' && i.status !== 'error');
  const seen = new Set(existing.filter((i) => i.status !== 'canceled').map((i) => i.fingerprint));
  let count = live.length;
  files.forEach((f, index) => {
    const reject = (code: PhotoErrorCode, detail?: string) =>
      out.rejected.push({ index, name: f.name, error: { code, retryable: false, detail } });
    const type = sniffImage(f.head);
    if (!type || !opts.accept.includes(type)) return reject('type-not-allowed');
    if (count >= opts.maxFiles) return reject('too-many');
    if (f.size > opts.maxFileBytes) return reject('file-too-large');
    const header = readHeader(f.head, type);
    if (!header) return reject('decode-failed');
    if (header.width !== null && header.height !== null && header.width * header.height > opts.maxPixels)
      return reject('too-many-pixels');
    const fingerprint = fingerprintOf(f);
    if (seen.has(fingerprint)) return reject('duplicate');
    seen.add(fingerprint);
    count += 1;
    out.accepted.push({ index, type, header, fingerprint });
  });
  return out;
}

/* ------------------------------------------------------------------- crop */

const clamp = (n: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, n));

/** Keep a rectangle inside 0..1 with a size that cannot vanish. */
const MIN_CROP = 0.05;
export function clampRect(r: CropRect, minSize = MIN_CROP): CropRect {
  const width = clamp(r.width, minSize, 1);
  const height = clamp(r.height, minSize, 1);
  return { x: clamp(r.x, 0, 1 - width), y: clamp(r.y, 0, 1 - height), width, height };
}

/**
 * The largest centred rectangle with the pixel aspect `aspect` (width / height)
 * inside an image of `imageAspect`; the whole image when `aspect` is null.
 */
export function initialCrop(aspect: number | null, imageAspect: number): CropRect {
  if (!aspect || !Number.isFinite(aspect) || !Number.isFinite(imageAspect) || imageAspect <= 0) {
    return { x: 0, y: 0, width: 1, height: 1 };
  }
  const width = aspect < imageAspect ? aspect / imageAspect : 1;
  const height = aspect < imageAspect ? 1 : imageAspect / aspect;
  return { x: (1 - width) / 2, y: (1 - height) / 2, width, height };
}

export const panRect = (r: CropRect, dx: number, dy: number): CropRect => clampRect({ ...r, x: r.x + dx, y: r.y + dy }, 0);

/** Scale about the centre; `factor` > 1 zooms in. The aspect of the rectangle is kept, and it stays inside the image. */
export function zoomRect(r: CropRect, factor: number): CropRect {
  const smallest = Math.min(r.width, r.height);
  const k = clamp(1 / clamp(factor, 0.1, 10), MIN_CROP / smallest, Math.min(1 / r.width, 1 / r.height));
  const width = r.width * k;
  const height = r.height * k;
  return clampRect({ x: r.x + (r.width - width) / 2, y: r.y + (r.height - height) / 2, width, height }, 0);
}

export const rotateQuarter = (q: Quarter, dir: 1 | -1): Quarter => ((q + (dir === 1 ? 90 : 270)) % 360) as Quarter;

/** The image aspect after a quarter turn. */
export const aspectAfter = (imageAspect: number, q: Quarter) => (q === 90 || q === 270 ? 1 / imageAspect : imageAspect);

/* ---------------------------------------------------------------- reducer */

export type PhotoAction =
  | { type: 'add'; items: readonly PhotoItem[] }
  | { type: 'reading'; id: string }
  | { type: 'processing'; id: string; progress?: number }
  | { type: 'processed'; id: string; output: ProcessedPhoto; previewUrl: string | null }
  | { type: 'upload'; id: string }
  | { type: 'progress'; id: string; value: number }
  | { type: 'resolved'; id: string; result: unknown }
  | { type: 'failed'; id: string; error: PhotoError }
  | { type: 'retry'; id: string }
  | { type: 'cancel'; id: string }
  | { type: 'remove'; id: string }
  | { type: 'alt'; id: string; alt: string }
  | { type: 'crop'; id: string; crop: PhotoItem['crop'] };

const LIVE: readonly PhotoStatus[] = ['queued', 'reading', 'processing', 'ready', 'uploading', 'error'];

/** The next state of the list. An action for an item that is gone or canceled changes nothing. */
export function reduce(items: readonly PhotoItem[], action: PhotoAction): readonly PhotoItem[] {
  if (action.type === 'add') return [...items, ...action.items];
  if (action.type === 'remove') return items.filter((i) => i.id !== action.id);
  const index = items.findIndex((i) => i.id === action.id);
  const item = items[index];
  if (!item) return items;
  const set = (patch: Partial<PhotoItem>) => items.map((i, n) => (n === index ? { ...i, ...patch } : i));
  if (action.type === 'cancel') {
    return item.status === 'done' || item.status === 'canceled'
      ? items
      : set({ status: 'canceled', progress: 0, error: { code: 'canceled', retryable: false } });
  }
  if (item.status === 'canceled') return items;
  switch (action.type) {
    case 'alt':
      return set({ alt: action.alt, output: item.output ? { ...item.output, alt: action.alt } : null });
    case 'crop':
      return set({ crop: action.crop });
    case 'reading':
      return item.status === 'queued' ? set({ status: 'reading', progress: 0 }) : items;
    case 'processing':
      return item.status === 'queued' || item.status === 'reading' || item.status === 'processing'
        ? set({ status: 'processing', progress: action.progress ?? item.progress })
        : items;
    case 'processed':
      return item.status === 'processing' || item.status === 'reading' || item.status === 'queued'
        ? set({
            status: 'ready',
            progress: 0,
            output: { ...action.output, alt: item.alt },
            previewUrl: action.previewUrl ?? item.previewUrl,
            error: null,
          })
        : items;
    case 'upload':
      return item.status === 'ready' ? set({ status: 'uploading', progress: 0, error: null }) : items;
    case 'progress':
      return item.status === 'uploading' || item.status === 'processing'
        ? set({ progress: clamp(action.value, 0, 1) })
        : items;
    case 'resolved':
      return item.status === 'uploading' ? set({ status: 'done', progress: 1, result: action.result, error: null }) : items;
    case 'failed':
      return item.status === 'uploading' || item.status === 'processing' || item.status === 'reading'
        ? set({ status: 'error', progress: 0, error: action.error })
        : items;
    default: {
      // retry
      if (item.status !== 'error' || !item.error) return items;
      const back: PhotoStatus = item.output ? 'ready' : 'queued';
      return set({ status: back, progress: 0, attempt: item.attempt + 1, error: null });
    }
  }
}

/** Ready items to start now: free slots only, none while offline, none in `manual` until released. */
export function nextToUpload(
  items: readonly PhotoItem[],
  opts: { concurrency: number; online: boolean; manual: boolean; released: boolean },
): string[] {
  if (!opts.online || (opts.manual && !opts.released)) return [];
  const busy = items.filter((i) => i.status === 'uploading').length;
  return items
    .filter((i) => i.status === 'ready')
    .slice(0, Math.max(0, opts.concurrency - busy))
    .map((i) => i.id);
}

export const isLive = (status: PhotoStatus) => LIVE.includes(status);

/** 1 s, 2 s, 4 s ... with up to 25% jitter. `random` is injected, so a test can pin it. */
export function retryDelay(attempt: number, random: () => number): number {
  return Math.round(1000 * 2 ** Math.max(0, attempt) * (1 + 0.25 * clamp(random(), 0, 1)));
}

/** Only an upload that said it is retryable is retried, and only up to `retries` times. */
export const shouldAutoRetry = (error: PhotoError, attempt: number, retries: number) =>
  error.code === 'upload-failed' && error.retryable && attempt < retries;

/* ---------------------------------------------------------------- words */

const KB = 1024;
export function formatBytes(n: number): string {
  if (n < KB) return `${n} B`;
  if (n < KB * KB) return `${Math.round(n / KB)} KB`;
  return `${(n / KB / KB).toFixed(1)} MB`;
}

export const DEFAULT_ERROR_TEXT: Record<PhotoErrorCode, string> = {
  'type-not-allowed': 'not a photo we can take',
  'too-many': 'too many photos',
  'file-too-large': 'the file is too large',
  'too-many-pixels': 'the picture is too large',
  duplicate: 'already added',
  'decode-failed': 'the photo could not be read',
  'unsupported-format': 'this browser cannot open that format',
  'encode-failed': 'the photo could not be prepared',
  'upload-failed': 'the connection dropped',
  canceled: 'canceled',
};

export interface AnnounceContext {
  online: boolean;
  wasOnline: boolean;
  text?: Partial<Record<PhotoErrorCode, string>>;
}

/** What a screen reader hears for a change of state. Nothing on the first render; no per-percent text. */
export function announcements(
  prev: readonly PhotoItem[] | null,
  next: readonly PhotoItem[],
  ctx: AnnounceContext,
): string[] {
  if (prev === null) return [];
  const out: string[] = [];
  const before = new Map(prev.map((i) => [i.id, i]));
  const added = next.filter((i) => !before.has(i.id)).length;
  if (added > 0) out.push(`${added} photo${added === 1 ? '' : 's'} added`);
  next.forEach((item, index) => {
    const old = before.get(item.id);
    if (!old || old.status === item.status) return;
    if (item.status === 'done') out.push(`Photo ${index + 1} of ${next.length} uploaded`);
    if (item.status === 'error' && item.error) {
      const why = ctx.text?.[item.error.code] ?? DEFAULT_ERROR_TEXT[item.error.code];
      out.push(`Photo ${index + 1} failed: ${why}. Try again is available`);
    }
  });
  if (!ctx.online && ctx.wasOnline) out.push('Waiting for a connection');
  return out;
}

/**
 * @interlace/ui — PhotoUpload model
 *
 * Everything PhotoUpload decides, with no DOM, no React and no clock: what a
 * file is (by its bytes, never its name), what it says about its owner and
 * how to remove that, whether it needs resizing, the crop maths, the item
 * reducer, the retry delay and what a screen reader is told. The component
 * and the browser runtime only carry out what this file plans.
 *
 * Metadata is removed byte for byte (JPEG APP1 Exif/XMP, APP13 IPTC, COM;
 * PNG eXIf, tEXt, zTXt, iTXt, tIME; WebP EXIF, XMP). Colour profiles stay, so
 * colour does not shift.
 */

import type { CropRect, EncodePlan, Quarter } from '@/components/ui/patterns/photo-upload-model';

/**
 * @interlace/ui — PhotoUpload runtime
 *
 * The only file that touches the browser's image APIs. `ImageRuntime` is the
 * seam: the component and its tests talk to the type, so a test substitutes a
 * fake, an agent a headless one, an app a HEIC decoder or a worker.
 *
 * A canvas redraw carries no metadata by construction, which is why every
 * re-encoded photo leaves with none. Nothing here makes a network request.
 */

/** A decoded picture, opaque to everyone but the runtime that made it. */
export interface DecodedImage {
  /** Pixels of the image as shown: already oriented. */
  width: number;
  height: number;
  /** The runtime's own handle (an `ImageBitmap` in the browser). */
  handle: unknown;
}

export interface ImageRuntime {
  /** Reads and orients a picture. Resolves null when this browser cannot decode the type. */
  decode(
    blob: Blob,
    opts: { maxEdge: number; signal: AbortSignal; hint?: { width: number; height: number } },
  ): Promise<DecodedImage | null>;
  /** Draws the oriented, turned, cropped, resized image and encodes it. */
  encode(img: DecodedImage, plan: EncodePlan, signal: AbortSignal): Promise<Blob>;
  /** A small preview, longest edge `edge`. */
  thumbnail(img: DecodedImage, edge: number): Promise<Blob>;
  createObjectURL(blob: Blob): string;
  revokeObjectURL(url: string): void;
  /** Release the decoded pixels. */
  dispose?(img: DecodedImage): void;
}

type Canvas2D = OffscreenCanvasRenderingContext2D | CanvasRenderingContext2D;
interface Surface {
  ctx: Canvas2D;
  toBlob(type: string, quality: number): Promise<Blob>;
}

function surface(width: number, height: number): Surface {
  if (typeof OffscreenCanvas !== 'undefined') {
    const canvas = new OffscreenCanvas(width, height);
    const ctx = canvas.getContext('2d');
    if (ctx) return { ctx, toBlob: (type, quality) => canvas.convertToBlob({ type, quality }) };
  }
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('no 2d canvas');
  return {
    ctx,
    toBlob: (type, quality) =>
      new Promise((resolve, reject) =>
        canvas.toBlob((b) => (b ? resolve(b) : reject(new Error('encode failed'))), type, quality),
      ),
  };
}

const bitmapOf = (img: DecodedImage) => img.handle as ImageBitmap;
const turned = (q: Quarter) => q === 90 || q === 270;

/** The image turned by `quarter`, on its own surface (the bitmap itself when it is not turned). */
function rotated(img: DecodedImage, quarter: Quarter): { source: CanvasImageSource; width: number; height: number } {
  if (quarter === 0) return { source: bitmapOf(img), width: img.width, height: img.height };
  const w = turned(quarter) ? img.height : img.width;
  const h = turned(quarter) ? img.width : img.height;
  const s = surface(w, h);
  s.ctx.translate(w / 2, h / 2);
  s.ctx.rotate((quarter * Math.PI) / 180);
  s.ctx.drawImage(bitmapOf(img), -img.width / 2, -img.height / 2);
  // `surface` hides the canvas; draw it back through a bitmap-free path.
  return { source: (s.ctx.canvas as CanvasImageSource), width: w, height: h };
}

function draw(img: DecodedImage, quarter: Quarter, crop: CropRect | null, width: number, height: number, flatten: boolean) {
  const s = surface(width, height);
  if (flatten) {
    s.ctx.fillStyle = '#fff';
    s.ctx.fillRect(0, 0, width, height);
  }
  const r = rotated(img, quarter);
  const c = crop ?? { x: 0, y: 0, width: 1, height: 1 };
  s.ctx.drawImage(r.source, c.x * r.width, c.y * r.height, c.width * r.width, c.height * r.height, 0, 0, width, height);
  return s;
}

export const browserRuntime: ImageRuntime = {
  async decode(blob, { maxEdge, signal, hint }) {
    if (typeof createImageBitmap !== 'function') return null;
    try {
      const scale = hint ? Math.min(1, maxEdge / Math.max(hint.width, hint.height, 1)) : 1;
      const options: ImageBitmapOptions = { imageOrientation: 'from-image' };
      if (hint && scale < 1) {
        options.resizeWidth = Math.max(1, Math.round(hint.width * scale));
        options.resizeHeight = Math.max(1, Math.round(hint.height * scale));
        options.resizeQuality = 'high';
      }
      const bitmap = await createImageBitmap(blob, options);
      if (signal.aborted) {
        bitmap.close();
        return null;
      }
      return { width: bitmap.width, height: bitmap.height, handle: bitmap };
    } catch {
      return null;
    }
  },
  async encode(img, plan, signal) {
    const width = plan.width || img.width;
    const height = plan.height || img.height;
    const s = draw(img, plan.quarter, plan.crop, width, height, plan.type === 'image/jpeg');
    if (signal.aborted) throw new DOMException('aborted', 'AbortError');
    return s.toBlob(plan.type, plan.quality);
  },
  async thumbnail(img, edge) {
    const k = Math.min(1, edge / Math.max(img.width, img.height, 1));
    const s = draw(img, 0, null, Math.max(1, Math.round(img.width * k)), Math.max(1, Math.round(img.height * k)), true);
    return s.toBlob('image/jpeg', 0.7);
  },
  createObjectURL: (blob) => URL.createObjectURL(blob),
  revokeObjectURL: (url) => URL.revokeObjectURL(url),
  dispose(img) {
    (img.handle as ImageBitmap | undefined)?.close?.();
  },
};
